-- CLIENT-CONFIG / RETA — Catálogo oficial de actividades (CNAE-2009 + IAE).
-- Fuentes oficiales: INE (estructura_cnae2009.xls) y AEAT (Epigrafes_x_EEDD.xlsx).
-- Cargado desde los ficheros oficiales (no transcrito a mano).
CREATE TABLE IF NOT EXISTS activity_catalog (
    id BIGINT NOT NULL AUTO_INCREMENT,
    catalog_type VARCHAR(8) NOT NULL,        -- CNAE | IAE
    code VARCHAR(20) NOT NULL,
    description VARCHAR(300) NOT NULL,
    level INT NULL,                          -- CNAE: 1 secc,2 div,3 grupo,4 clase
    active BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT pk_activity_catalog PRIMARY KEY (id),
    INDEX ix_activity_catalog_type (catalog_type, code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

